const byId = new Map(TITLES.map((t) => [t.id, t]));

export function getTitle(id: string): Title | undefined {
  return byId.get(id);
}

function pick(ids: string[]): Title[] {
  return ids.map((id) => {
    const title = byId.get(id);
    if (!title) throw new Error(`Unknown title id in rail: ${id}`);
    return title;
  });
}

